package app.multimin.ui;
import app.multimin.backend.PythonBridge;import app.multimin.model.*;import javax.swing.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;
public class NativeGamePipelineCheck {
 static Object field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 public static void main(String[] args)throws Exception{SwingUtilities.invokeAndWait(()->{try{
  System.setProperty("multimin.dev.gameCapture","true");PythonBridge backend=new PythonBridge();MainWindow window=new MainWindow(backend);View view=(View)field(window,"activeView");view.sources.clear();Source source=new Source("Controlled DX11 test",Source.Kind.GAME);source.nativeGameTest=true;source.x=source.y=0;source.scale=100;source.captureFramePath=Path.of("test-native.game").toAbsolutePath().toString();view.sources.addElement(source);window.setVisible(true);backend.start(window::setBackendStatus);backend.startGameCapture(source.captureFramePath);long start=System.nanoTime();Set<Integer> colors=new HashSet<>();int[] ticks={0};
  new javax.swing.Timer(1000,e->{try{if(source.liveFrame!=null)colors.add(source.liveFrame.getRGB(source.liveFrame.getWidth()/2,source.liveFrame.getHeight()/2));if(++ticks[0]<7)return;((javax.swing.Timer)e.getSource()).stop();if(source.capturedFrames<10||colors.size()<2||source.presentedFrames<2)throw new AssertionError("Missing live native frames: delivered="+source.capturedFrames+" changing colors="+colors.size()+" painted="+source.presentedFrames);System.out.printf(java.util.Locale.ROOT,"Native test delivered %.1f FPS, %d painted frames, %d sampled colors%n",source.capturedFrames*1e9/(System.nanoTime()-start),source.presentedFrames,colors.size());Process process=(Process)field(backend,"process");String interpreter=process.info().command().orElse("");if(!interpreter.contains("package\\image\\MultiMini\\app\\python\\runtime"))throw new AssertionError("Not using packaged backend: "+interpreter);List<ProcessHandle> children=process.descendants().toList();Method stop=MainWindow.class.getDeclaredMethod("shutdownServices");stop.setAccessible(true);stop.invoke(window);window.dispose();for(ProcessHandle child:children)if(child.isAlive())throw new AssertionError("Native helper still alive after shutdown");System.out.println("PASS: packaged native frames → Python → Java preview, continuous changing pixels and helper cleanup");System.exit(0);}catch(Throwable error){error.printStackTrace();backend.close();window.dispose();System.exit(1);}}).start();
 }catch(Exception error){throw new RuntimeException(error);}});}
}
